#define MAXN 1000000

typedef struct {
    long long dist;
    int node;
} HeapNode;

typedef struct {
    HeapNode *arr;
    int size;
    int cap;
} MinHeap;

void heap_push(MinHeap *heap, int node, long long dist) {
    if (heap->size == heap->cap) {
        heap->cap *= 2;
        heap->arr = realloc(heap->arr, heap->cap * sizeof(HeapNode));
    }
    int i = heap->size++;
    heap->arr[i].node = node;
    heap->arr[i].dist = dist;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap->arr[p].dist <= heap->arr[i].dist) break;
        HeapNode tmp = heap->arr[p];
        heap->arr[p] = heap->arr[i];
        heap->arr[i] = tmp;
        i = p;
    }
}

HeapNode heap_pop(MinHeap *heap) {
    HeapNode top = heap->arr[0];
    heap->arr[0] = heap->arr[--heap->size];
    int i = 0;
    while (1) {
        int smallest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left < heap->size && heap->arr[left].dist < heap->arr[smallest].dist)
            smallest = left;
        if (right < heap->size && heap->arr[right].dist < heap->arr[smallest].dist)
            smallest = right;
        if (smallest == i) break;
        HeapNode tmp = heap->arr[i];
        heap->arr[i] = heap->arr[smallest];
        heap->arr[smallest] = tmp;
        i = smallest;
    }
    return top;
}

