long long solve_one(long long N, long long A, long long B, long long C, long long D) {
    if (N == 0) return 0;
    long long limit = N * 2 + 10;
    if (limit < 10) limit = 10;
    long long size = (long long)limit + 1;

    long long *dist = (long long*)malloc((size_t)size * sizeof(long long));
    for (long long i = 0; i < size; i++) dist[i] = LLONG_MAX;

    MinHeap heap;
    heap.cap = 1024;
    heap.size = 0;
    heap.arr = (HeapNode*)malloc(heap.cap * sizeof(HeapNode));

    dist[0] = 0;
    heap_push(&heap, 0, 0);

    while (heap.size > 0) {
        HeapNode cur = heap_pop(&heap);
        long long d = cur.dist;
        int u = cur.node;
        if (d != dist[u]) continue;
        if (u == N) {
            long long ans = dist[N];
            free(dist);
            free(heap.arr);
            return ans;
        }

        // +1
        if (u + 1 <= limit && d + D < dist[u + 1]) {
            dist[u + 1] = d + D;
            heap_push(&heap, u + 1, d + D);
        }
        // -1
        if (u - 1 >= 0 && d + D < dist[u - 1]) {
            dist[u - 1] = d + D;
            heap_push(&heap, u - 1, d + D);
        }
        // *2
        if (u * 2 <= limit && d + A < dist[u * 2]) {
            dist[u * 2] = d + A;
            heap_push(&heap, u * 2, d + A);
        }
        // *3
        if (u * 3 <= limit && d + B < dist[u * 3]) {
            dist[u * 3] = d + B;
            heap_push(&heap, u * 3, d + B);
        }
        // *5
        if (u * 5 <= limit && d + C < dist[u * 5]) {
            dist[u * 5] = d + C;
            heap_push(&heap, u * 5, d + C);
        }
    }

    long long ans = dist[N];
    free(dist);
    free(heap.arr);
    return ans;
}

