static void vec_push(Vec *v, ll n, ll cost) {
    if (v->size == v->cap) {
        int ncap = (v->cap == 0 ? 16 : v->cap * 2);
        State *na = (State*)realloc(v->a, sizeof(State) * ncap);
        if (!na) exit(1);
        v->a = na;
        v->cap = ncap;
    }
    v->a[v->size].n = n;
    v->a[v->size].cost = cost;
    v->size++;
}

static int cmp_state(const void *p1, const void *p2) {
