/*
We solve recursively from n down to 0.

For target n:
- Directly: n * D
- For each k in {2,3,5} with multiply cost X:
    Let q = n / k, r = n % k
    We can come from q by multiplying by k, then adjust by +r
      cost = f(q) + X + r*D
    Or from q+1 by multiplying by k, then adjust by -(k-r)
      cost = f(q+1) + X + (k-r)*D   (only if r != 0)

Memoization is used. Since each recursion only goes to roughly n/2, n/3, n/5,
number of states is small.
*/

typedef struct {
    State *a;
    int size;
    int cap;
} Map;

static void map_init(Map *m) {
    m->a = NULL;
    m->size = 0;
    m->cap = 0;
}

static ll map_get(Map *m, ll key, int *found) {
    int l = 0, r = m->size - 1;
    while (l <= r) {
        int mid = (l + r) >> 1;
        if (m->a[mid].n == key) {
            *found = 1;
            return m->a[mid].cost;
        }
        if (m->a[mid].n < key) l = mid + 1;
        else r = mid - 1;
    }
    *found = 0;
    return 0;
}

static void map_set(Map *m, ll key, ll val) {
    int l = 0, r = m->size - 1, pos = 0;
    while (l <= r) {
        int mid = (l + r) >> 1;
        if (m->a[mid].n == key) {
            m->a[mid].cost = val;
            return;
        }
        if (m->a[mid].n < key) l = mid + 1;
        else r = mid - 1;
    }
    pos = l;
    if (m->size == m->cap) {
        int ncap = (m->cap == 0 ? 16 : m->cap * 2);
        State *na = (State*)realloc(m->a, sizeof(State) * ncap);
        if (!na) exit(1);
        m->a = na;
        m->cap = ncap;
    }
    for (int i = m->size; i > pos; --i) m->a[i] = m->a[i - 1];
    m->a[pos].n = key;
    m->a[pos].cost = val;
    m->size++;
}

static ll A, B, C, D;

static ll solve(ll n, Map *memo) {
    if (n <= 0) return 0;
    int found;
    ll got = map_get(memo, n, &found);
    if (found) return got;

    __int128 base = (__int128)n * D;
    ll ans = (base > LLONG_MAX ? LLONG_MAX : (ll)base);

    ll q, r, cand;

    // divide by 2 in reverse
    q = n / 2; r = n % 2;
    cand = solve(q, memo);
    if (cand < LLONG_MAX / 2) {
        __int128 t = (__int128)cand + A + (__int128)r * D;
        if (t < ans) ans = (ll)t;
    }
    if (r != 0) {
        cand = solve(q + 1, memo);
        if (cand < LLONG_MAX / 2) {
            __int128 t = (__int128)cand + A + (__int128)(2 - r) * D;
            if (t < ans) ans = (ll)t;
        }
    }

    // divide by 3 in reverse
    q = n / 3; r = n % 3;
    cand = solve(q, memo);
    if (cand < LLONG_MAX / 2) {
        __int128 t = (__int128)cand + B + (__int128)r * D;
        if (t < ans) ans = (ll)t;
    }
    if (r != 0) {
        cand = solve(q + 1, memo);
        if (cand < LLONG_MAX / 2) {
            __int128 t = (__int128)cand + B + (__int128)(3 - r) * D;
            if (t < ans) ans = (ll)t;
        }
    }

    // divide by 5 in reverse
    q = n / 5; r = n % 5;
    cand = solve(q, memo);
    if (cand < LLONG_MAX / 2) {
        __int128 t = (__int128)cand + C + (__int128)r * D;
        if (t < ans) ans = (ll)t;
    }
    if (r != 0) {
        cand = solve(q + 1, memo);
        if (cand < LLONG_MAX / 2) {
            __int128 t = (__int128)cand + C + (__int128)(5 - r) * D;
            if (t < ans) ans = (ll)t;
        }
    }

    map_set(memo, n, ans);
    return ans;
}

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;

    while (T--) {
        ll N;
        scanf("%lld %lld %lld %lld %lld", &N, &A, &B, &C, &D);

        Map memo;
        map_init(&memo);
        map_set(&memo, 0, 0);

        ll ans = solve(N, &memo);
        printf("%lld\n", ans);

        free(memo.a);
    }
    return 0;
}

