int64 solve_case(int64 N, int64 A, int64 B, int64 C, int64 D) {
    // Dijkstra from N to 0
    map<int64, int64> dist;
    priority_queue<pair<int64, int64>, vector<pair<int64, int64>>, greater<>> pq;
    dist[N] = 0;
    pq.push({0, N});

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        if (u == 0) return d;

        // Try /2
        if (u % 2 == 0) {
            int64 v = u / 2;
            int64 nd = d + A;
            if (!dist.count(v) || nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        } else {
            // go to nearest divisible by 2 via +/-1
            for (int64 v : {u-1, u+1}) {
                if (v < 0) continue;
                int64 nd = d + D + A;
                if (!dist.count(v/2) || nd < dist[v/2]) {
                    dist[v/2] = nd;
                    pq.push({nd, v/2});
                }
            }
        }

        // Try /3
        if (u % 3 == 0) {
            int64 v = u / 3;
            int64 nd = d + B;
            if (!dist.count(v) || nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        } else {
            int64 r = u % 3;
            int64 v1 = (u - r) / 3;
            int64 v2 = (u + (3 - r)) / 3;
            if (v1 >= 0) {
                int64 nd = d + D * r + B;
                if (!dist.count(v1) || nd < dist[v1]) {
                    dist[v1] = nd;
                    pq.push({nd, v1});
                }
            }
            if (v2 >= 0) {
                int64 nd = d + D * (3 - r) + B;
                if (!dist.count(v2) || nd < dist[v2]) {
                    dist[v2] = nd;
                    pq.push({nd, v2});
                }
            }
        }

        // Try /5
        if (u % 5 == 0) {
            int64 v = u / 5;
            int64 nd = d + C;
            if (!dist.count(v) || nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        } else {
            int64 r = u % 5;
            int64 v1 = (u - r) / 5;
            int64 v2 = (u + (5 - r)) / 5;
            if (v1 >= 0) {
                int64 nd = d + D * r + C;
                if (!dist.count(v1) || nd < dist[v1]) {
                    dist[v1] = nd;
                    pq.push({nd, v1});
                }
            }
            if (v2 >= 0) {
                int64 nd = d + D * (5 - r) + C;
                if (!dist.count(v2) || nd < dist[v2]) {
                    dist[v2] = nd;
                    pq.push({nd, v2});
                }
            }
        }

        // Also consider just decreasing by 1 repeatedly
        if (u > 0) {
            int64 nd = d + D;
            if (!dist.count(u-1) || nd < dist[u-1]) {
                dist[u-1] = nd;
                pq.push({nd, u-1});
            }
        }
    }
    return dist[0];
}

