using int64 = long long;
using i128 = __int128_t;

static unordered_map<long long, long long> memo;
static long long A, B, C, D;

long long solve(long long n) {
    if (n == 0) return 0;
    if (n == 1) return D;

    auto it = memo.find(n);
    if (it != memo.end()) return it->second;

    // Baseline: reach n only by +/-1 from 0
    long long ans = (long long)((i128)n * D);

    auto relax = [&](long long k, long long costMul) {
        long long q = n / k;
        long long r = n % k;

        // Come from q, then multiply by k, then +r times
        {
            long long cand = solve(q);
            cand = min((i128)LLONG_MAX, (i128)cand + costMul + (i128)r * D);
            ans = min(ans, cand);
        }

        // Come from q+1, then multiply by k, then -(k-r) times
        if (r != 0) {
            long long cand = solve(q + 1);
            cand = min((i128)LLONG_MAX, (i128)cand + costMul + (i128)(k - r) * D);
            ans = min(ans, cand);
        }
    };

    relax(2, A);
    relax(3, B);
    relax(5, C);

    memo[n] = ans;
    return ans;
}

