        Map<Long, Long> dist = new HashMap<>();
        pq.offer(new long[]{0, 0});
        dist.put(0L, 0L);

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long x = cur[0];
            long d = cur[1];
            if (d != dist.get(x)) continue;
            if (x == N) return d;

            // Try all operations
            // +1 and -1
            if (x + 1 <= N + 200 && (!dist.containsKey(x + 1) || d + D < dist.get(x + 1))) {
                dist.put(x + 1, d + D);
                pq.offer(new long[]{x + 1, d + D});
            }
            if (x - 1 >= 0 && (!dist.containsKey(x - 1) || d + D < dist.get(x - 1))) {
                dist.put(x - 1, d + D);
                pq.offer(new long[]{x - 1, d + D});
            }
            // *2
            if (x * 2 <= N * 2 && (!dist.containsKey(x * 2) || d + A < dist.get(x * 2))) {
                dist.put(x * 2, d + A);
                pq.offer(new long[]{x * 2, d + A});
