import java.io.*;
import java.util.*;

/*
 * Minimum cost to reach N from 0 using:
 * x -> 2x (cost A)
 * x -> 3x (cost B)
 * x -> 5x (cost C)
 * x -> x+1 or x-1 (cost D)
 *
 * Standard approach: solve backwards from N to 0 with memoization.
 * Let f(n) = minimum cost to reduce n to 0 using reverse operations:
 *   n -> n/2 if divisible by 2 (cost A)
 *   n -> n/3 if divisible by 3 (cost B)
 *   n -> n/5 if divisible by 5 (cost C)
 *   n -> n±1 (cost D)
 *
 * For each divisor k in {2,3,5}, from n we may:
 *   - decrease by r = n % k to nearest lower multiple, then divide
 *   - increase by k-r to nearest upper multiple, then divide
 *
 * So:
 *   f(n) = min(
 *      n * D,
 *      f(n/2) + A + (n%2)*D,
 *      f((n+1)/2) + A + (2-n%2)%2 * D, etc...
 *   )
 *
 * Memoization keeps states small (O(log N) distinct useful states).
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long A, B, C, D;
    static HashMap<Long, Long> memo;

    static long solve(long n) {
        if (n == 0) return 0;
        if (n == 1) return D;
        Long cached = memo.get(n);
        if (cached != null) return cached;

        long ans = safeMul(n, D); // just use +/-1 only

        ans = Math.min(ans, via(n, 2, A));
        ans = Math.min(ans, via(n, 3, B));
        ans = Math.min(ans, via(n, 5, C));

        memo.put(n, ans);
        return ans;
    }

    static long via(long n, int k, long costDiv) {
        long rem = n % k;

        // Move down to nearest multiple of k, then divide
        long down = safeAdd(solve((n - rem) / k), safeAdd(costDiv, safeMul(rem, D)));

        // Move up to nearest multiple of k, then divide
        long upSteps = (k - rem) % k;
        long up = safeAdd(solve((n + upSteps) / k), safeAdd(costDiv, safeMul(upSteps, D)));

        return Math.min(down, up);
    }

    static long safeMul(long x, long y) {
        if (x == 0 || y == 0) return 0;
        if (x > Long.MAX_VALUE / y) return Long.MAX_VALUE / 4;
        return x * y;
    }

    static long safeAdd(long x, long y) {
        if (x >= Long.MAX_VALUE / 4 || y >= Long.MAX_VALUE / 4) return Long.MAX_VALUE / 4;
        if (x > Long.MAX_VALUE - y) return Long.MAX_VALUE / 4;
        return x + y;
    }

    public static void main(String[] args) throws Exception {
